INSERT INTO `changelog_audit_detail` VALUES ('0048fb1e8a358db310a99f1ef35792ed','\nALTER TABLE `matrix_attribute`\n    CHANGE `name` `name` VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL   COMMENT \'属性名称\',    ADD COLUMN `unique_identifier` VARCHAR(50) NOT NULL   COMMENT \'属性唯一标识\' AFTER `name`;'),('011def9256a304fe0d2649f85713a13e','\nCREATE TABLE `alert_topo_widget`\n(\n    `id`        bigint NOT NULL COMMENT \'id\',\n    `name`      varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'唯一标识，x6注册时用\',\n    `type`      varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT \'图元类型\',\n    `icon`      varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT \'图标\',\n    `label`     varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'名称\',\n    `shape`     varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT \'形状，和前端对应\',\n    `is_active` tinyint                                                       DEFAULT NULL COMMENT \'是否激活\',\n    `config`    longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT \'配置\',\n    PRIMARY KEY (`id`) USING BTREE,\n    UNIQUE KEY `uk_name` (`name`) USING BTREE,\n    KEY `idx_type_id` (`shape`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('01bb1d799880a6cf8dcaba245d00850b','\nALTER TABLE `processtask_step_in_operation`    ADD COLUMN `server_id` BIGINT NULL COMMENT \'服务器ID\' AFTER `expire_time`;'),('01e139b0f95c7fdcd27f8cf791a04dab','ALTER TABLE `user_session` ADD PRIMARY KEY (`token_hash`) USING HASH;'),('01f9f91a41037f1ced17bb8e05649c79','ALTER TABLE `deploy_app_env_auto_config` ADD COLUMN `type` enum(\'text\',\'password\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT \'text\' COMMENT \'变量类型\' AFTER `key`;'),('0303c44b904f2a504b7cbb72d48b7eda','ALTER TABLE `runner_map` DROP PRIMARY KEY, ADD PRIMARY K