RY KEY (`eoa_step_user_content_id`,`file_id`),    KEY `idx_file_id` (`file_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'eoa步骤回复附件表\';'),('3071128c8116708e926bbbcd5c4d17db','\nreplace into cmdb_viewconst (id, name, label, sort, show_type)values (3, \'_typeName\', \'类型\', 2, \'all\');'),('311249fde11666a04a99c5abd2966d62','ALTER TABLE `cmdb_sync_mapping`    MODIFY COLUMN `action` enum(\'insert\',\'replace\',\'delete\',\'update\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT \'insert\' COMMENT \'动作\' AFTER `field`;'),('314f2f753194657bd0c08caf736e3f41','\nALTER TABLE `datawarehouse_datasource`    CHANGE `db_type` `db_type` ENUM (\'mysql\', \'mongodb\', \'jdbc\') CHARSET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT \'mysql\' NULL COMMENT \'数据库类型\';'),('337c8a2f4b197db4a8b67dce532cbc91','CREATE TABLE `diagram_check_audit`(    `id`                 bigint       NOT NULL COMMENT \'id\',    `diagram_version_id` bigint                                                                                             DEFAULT NULL COMMENT \'版本id\',    `check_user`         char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                          DEFAULT NULL COMMENT \'审核用户\',    `action`             enum (\'pass\',\'reject\',\'recall\',\'active\',\'commit\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'动作\',    `check_time`         timestamp(3) NULL                                                                                  DEFAULT NULL COMMENT \'审核时间\',    `description`        text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT \'描述\',    PRIMARY KEY (`id`),    KEY `idx_version_id` (`diagram_version_id`) USING BTREE) ENGINE = InnoDB  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('338f5e77e8874defdc86ca7878dd78eb','\nCREATE TABLE IF NOT EXISTS `processtask_collection_definition`\n(\n    `id`                  bigint NOT NULL,\n    `system`              varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'应用系统\',\n    `request`             varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'需求编号\',\n    `env`                 varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'环境\',\n    `collection_data`     longtext COLLATE utf8mb4_general_ci COMMENT \'工单集合数据\',\n    `processtask_id`      bigint                                  DEFAULT NULL COMMENT \'工单id\',\n    `processtask_step_id` bigint                                  DEFAULT NULL COMMENT \'工单步骤id\',\n    PRIMARY KEY (`id`),\n    UNIQUE KEY `uk` (`system`, `request`, `env`) USING BTREE,\n    KEY `idx_processtask_id` (`processtask_id`) USING BTREE,\n    KEY `idx_processtask_step_id` (`processtask_step_id`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci COMMENT =\'工单集合节点对工单集合的定义数据\';'),('33d747bce279f9346feda96ca50ceeec','DROP FUNCTION IF EXISTS `generateSnowflakeId`;'),('3514f030ff7b8d09fab9c14bb9c0beb9','ALTER TABLE `role` ADD COLUMN `env` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT \'生效环境\' AFTER `description`;'),('357ec6a253bbcc42aba4aac216ca0052','ALTER TABLE `eoa_step_user_content`DROP COLUMN `file_id_list_hash`,  CHANGE `id` `id` BIGINT NOT NULL   COMMENT \'id\',  CHANGE `eoa_id` `eoa_id` BIGINT NOT NULL   COMMENT \'eoa的id\',  CHANGE `eoa_step_id` `eoa_step_id` BIGINT NOT NULL   COMMENT \'eoa步骤的id\',  CHANGE `type` `type` VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL   COMMENT \'类型\',  CHANGE `content_hash` `content_hash` CHAR(32) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL   COMMENT \'内容的hash值\',  CHANGE `fcu` `fcu` CHAR(32) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL   COMMENT \'创建人\',  CHANGE `fcd` `fcd` TIMESTAMP(3) NOT NULL   COMMENT \'创建时间\',COMMENT=\'eoa步骤处理信息表\';'),('357f2e4044f02e05dc51cd639021bb9c','CREATE TABLE IF NOT EXISTS `extramenu`(    `id`          BIGINT                                                       NOT NULL COMMENT \'id\',    `name`        VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT \'名称\',    `type`        tinyint(1)                                                   NOT NULL DEFAULT \'0\' COMMENT \'类型，0：目录，1：菜单\',    `is_active`   tinyint(1)                                                   NOT NULL DEFAULT \'0\' COMMENT \'是否激活\',    `url`         VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci         DEFAULT NULL COMMENT \'跳转链接\',    `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci        DEFAULT NULL COMMENT \'描述\',    `parent_id`   BIGINT                                                                DEFAULT NULL COMMENT \'父id\',    `lft`         INT                                                                   DEFAULT NULL COMMENT \'左编码\',    `rht`         INT                                                                   DEFAULT NULL COMMENT \'右编码\',    KEY `idx_lft_rht` (`lft`, `rht`),    KEY `idx_parent_id` (`parent_id`)) ENGINE = INNODB  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci COMMENT =\'附加菜单表\';'),('360b5f54e341086bda6af14f8261d46e','\nALTER TABLE `deploy_sql_detail`    MODIFY COLUMN `sql_file` VARCHAR(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'sql文件名称\';'),('36330f0ded9b17adb8cb95e19adf6fa3','\nALTER TABLE `process_workcenter`\nADD COLUMN `fcd` timestamp(3) NULL COMMENT \'创建时间\' AFTER `thead_config_hash`,\nADD COLUMN `fcu` char(32) NULL COMMENT \'创建人\' AFTER `fcd`,ADD COLUMN `is_active` tinyint(1) NULL DEFAULT 0 COMMENT \'是否禁用\' AFTER `fcu`;'),('36885f625e45003532203f29e35670cf','CREATE TABLE IF NOT EXISTS `eoa_template` (    `id` bigint NOT NULL COMMENT \'唯一标识\',    `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT \'名称\',    `description` mediumtext COLLATE utf8mb4_general_ci COMMENT \'描述\',    `config` mediumtext COLLATE utf8mb4_general_ci NOT NULL COMMENT \'配置信息\',    `fcu` char(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT \'创建者\',    `fcd` timestamp(3) NOT NULL COMMENT \'创建时间\',    `lcu` char(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT \'修改者\',    `lcd` timestamp(3) NOT NULL COMMENT \'修改时间\',    PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;'),('372757cbaefeffe98d1f23777325e5df','\nALTER TABLE `cmdb_global_attritem`    ADD UNIQUE INDEX `uk`(`attr_id`, `value`) USING BTREE;'),('3734e8d1a81ff0700d6d22edaa5661e9','\nCREATE FUNCTION `generateSnowflakeId`() RETURNS BIGINT\nBEGIN\n    DECLARE SCHEDULE_SERVER_ID BIGINT DEFAULT 1;\n    DECLARE START_TIMESTAMP BIGINT DEFAULT 1577808000;\n    DECLARE SEQUENCE_BIT BIGINT DEFAULT 13;\n    DECLARE MACHINE_BIT BIGINT DEFAULT 10;\n    DECLARE TIMESTAMP_LEFT BIGINT DEFAULT SEQUENCE_BIT + MACHINE_BIT;\n    DECLARE MAX_SEQUENCE BIGINT DEFAULT ~(-1 << SEQUENCE_BIT);\n    DECLARE MAX_MACHINE_ID BIGINT DEFAULT ~(-1 << MACHINE_BIT);\n    DECLARE machineIdPart BIGINT DEFAULT (SCHEDULE_SERVER_ID & MAX_MACHINE_ID) << SEQUENCE_BIT;\n    DECLARE currentStamp BIGINT;\n    SET currentStamp = UNIX_TIMESTAMP(NOW());\n    IF currentStamp < @lastStamp THEN\n        WHILE currentStamp < @lastStamp DO\n		    SET currentStamp = UNIX_TIMESTAMP(NOW());\n        END WHILE;\n    END IF;\n    IF currentStamp = @lastStamp THEN\n        SET @sequence = (@sequence + 1) & MAX_SEQUENCE;\n        IF @sequence = 0 THEN\n            WHILE currentStamp < @lastStamp DO\n		        SET currentStamp = UNIX_TIMESTAMP(NOW());\n            END WHILE;\n        END IF;\n    ELSE\n        SET @sequence = 0;\n    END IF;\n    SET @lastStamp = currentStamp;\n    RETURN ((currentStamp - START_TIMESTAMP) << TIMESTAMP_LEFT) | machineIdPart | @sequence;END $$'),('37fdaef1a117d5bedbc860081e95e152','\nALTER TABLE `deploy_job`MODIFY COLUMN `app_system_id` bigint NULL COMMENT \'系统id\' AFTER `id`;'),('3824c9bc7934aed07626ad217c2ff8ac','ALTER TABLE `autoexec_job_phase_node` ADD COLUMN `error_type` int NULL COMMENT \'异常信息\' AFTER `update_tag`;'),('38b8757630e216e25369bbb889b7613e','\nALTER TABLE `extramenu`    ADD COLUMN `sort` int NULL COMMENT \'排序\' AFTER `parent_id`;'),('39087e884ea2c85923975813b14ca1e8','\nALTER TABLE `diagram_graph_version`    ADD COLUMN `is_end` tinyint NULL DEFAULT NULL COMMENT \'是否终结版本\' AFTER `is_editing`;'),('3aa0998280486d82d5c2ebeb7b6b9d18','\nCREATE TABLE `dr_preparation_job_problem`\n(\n    `id`         bigint    NOT NULL COMMENT \'id\',\n    `task_id`    bigint                                                                 DEFAULT NULL COMMENT \'任务id\',\n    `title`      varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci          DEFAULT NULL COMMENT \'标题\',\n    `content`    text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT \'内容\',\n    `status`     enum (\'open\',\'close\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'状态\',\n    `open_time`  timestamp NULL                                                         DEFAULT NULL COMMENT \'开启时间\',\n    `open_user`  char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci              DEFAULT NULL COMMENT \'开启用户\',\n    `close_time` timestamp NULL                                                         DEFAULT NULL COMMENT \'关闭时间\',\n    `close_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci              DEFAULT NULL COMMENT \'关闭用户\',\n    `solution`   text COLLATE utf8mb4_general_ci COMMENT \'解决方案\',\n    PRIMARY KEY (`id`),\n    KEY `idx_task_id` (`task_id`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('3ab53242dc490f16123556e966751f0f','\nCREATE TABLE IF NOT EXISTS `process_workcenter_thead_config` (\n  `hash` char(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT \'配置hash\',\n  `config` text COLLATE utf8mb4_general_ci COMMENT \'配置\',\n  PRIMARY KEY (`hash`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;'),('3b3a48fc4dfbf953285c8f4e2e9655b9','\nCREATE TABLE IF NOT EXISTS 