                              `start_time` datetime DEFAULT NULL,\n                               `end_time` datetime DEFAULT NULL,\n                               `preparation_id` bigint DEFAULT NULL,\n                               `fcu` char(32) COLLATE utf8mb4_general_ci DEFAULT NULL,\n                               `fcd` timestamp NULL DEFAULT NULL,\n                               `lcu` char(32) COLLATE utf8mb4_general_ci DEFAULT NULL,\n                               `lcd` timestamp NULL DEFAULT NULL,\n                               PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;'),('ab8500384bff9eed23b59d0345d5a0ac','ALTER TABLE `master_user` MODIFY COLUMN `pinyin` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT \'拼音\' AFTER `user_name`;'),('ab87eb5bac185fb63efcce877448ff90','\nCREATE TABLE IF NOT EXISTS `deploy_app_instance_blue_green`  (\n  `app_system_id` bigint NOT NULL COMMENT \'系统id\',\n  `app_module_id` bigint NOT NULL COMMENT \'模块id\',\n  `env_id` bigint NOT NULL COMMENT \'环境id\',\n  `resource_id` bigint NOT NULL COMMENT \'实例id\',\n  `blue_green_id` bigint DEFAULT NULL COMMENT \'蓝绿id\',\n  PRIMARY KEY (`app_system_id`,`app_module_id`,`env_id`,`resource_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'发布实例蓝绿关系表\';'),('abb775d12d32bb442d171b525571db25','ALTER TABLE `tenant_module_dmlsql` ADD COLUMN `ignored` tinyint(1) NULL COMMENT \'是否忽略，0:不忽略，1:已忽略，默认忽略\' AFTER `fcd`;'),('ac017950c1638a79f24deefcb30a34ff','ALTER TABLE `autoexec_job_phase_node_runner` DROP INDEX `idx_phaseId`,ADD INDEX `idx_nodeId`(`node_id`) USING BTREE;'),('ac6b27b74d514fae91884bb75a5be538','\nCREATE TABLE `dr_preparation_phase_task`\n(\n    `id`             bigint NOT NULL COMMENT \'id\',\n    `sort`           int                                                               DEFAULT NULL COMMENT \'排序\',\n    `uuid`           char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci         DEFAULT NULL COMMENT \'uuid\',\n    `name`           varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci     DEFAULT NULL COMMENT \'名称\',\n    `phase_id`       bigint                                                            DEFAULT NULL COMMENT \'阶段id\',\n    `service_id`     bigint                                                            DEFAULT NULL COMMENT \'服务id\',\n    `scene_id`       bigint                                                            DEFAULT NULL COMMENT \'场景id\',\n    `plan_time_cost` int                                                               DEFAULT NULL COMMENT \'计划耗时，单位分钟\',\n    `type`           enum (\'at\',\'mt\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'任务类型\',\n    `description`    varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci     DEFAULT NULL COMMENT \'描述\',\n    `color`          varchar(50) COLLATE utf8mb4_general_ci                            DEFAULT NULL COMMENT \'颜色\',\n    PRIMARY KEY (`id`),\n    KEY `idx_phase_id` (`phase_id`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('ac70c286b332e40a484b9e0b032b687f','\nALTER TABLE `tag`\nADD COLUMN `type` varchar(50) NULL COMMENT \'类型\' AFTER `name`,ADD UNIQUE INDEX `uniq_nametype`(`type`, `name`) USING BTREE;'),('ac7ced47d2b1c07e0709e970c9315b0a','\nINSERT IGNORE INTO `catalog_authority` (`catalog_uuid`, `type`, `uuid`, `action`)\nSELECT a.`uuid`, \'common\', \'alluser\', \'view\' FROM catalog a\nLEFT JOIN `catalog_authority` b ON b.`catalog_uuid` = a.`uuid`WHERE b.`catalog_uuid` IS NULL;'),('ac984bcca852bb3881d3267aa2312e66','\nALTER TABLE `process_workcenter_thead` \nDROP COLUMN `name`,\nDROP COLUMN `sort`,\nDROP COLUMN `is_show`,\nDROP COLUMN `width`,\nDROP COLUMN `type`,\nDROP COLUMN `disabled`,\nADD COLUMN `config_hash` char(32) NULL AFTER `user_uuid`,\nDROP PRIMARY KEY,\nADD PRIMARY KEY (`workcenter_uuid`, `user_uuid`),ADD INDEX `idx_hash`(`config_hash`) USING HASH;'),('acfaeded792ca2e13eb92f4b66469bca','\nCREATE TABLE IF NOT EXISTS `dr_user_type`\n(\n    `name`  varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,\n    `label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,\n    PRIMARY KEY (`name`) USING BTREE\n) ENGINE = InnoDB\n  CHARACTER SET = utf8mb4\n  COLLATE = utf8mb4_general_ci  ROW_FORMAT = Dynamic;'),('ad8548cea45c89bb5430ba124466aa72','ALTER TABLE `datasource` DROP INDEX `uk_tenant_uuid`;'),('ae6a622ed38ae652770035e04b417460','\nCREATE TABLE IF NOT EXISTS `server_run_time` (\n    `start_time` TIMESTAMP(3) NOT NULL COMMENT \'服务器启动时间\',\n    `server_id` INT NOT NULL COMMENT \'服务器ID\',\n    `heartbeat_time` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT \'心跳时间\',\n    PRIMARY KEY (`start_time`,`server_id`)) ENGINE=INNODB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'服务器运行时间表\';'),('af871bbb71c672462f612123fdc7bc99','\nCREATE TABLE `alert_subscribe_audit`\n(\n    `id`           bigint       NOT NULL,\n    `alert_id`     bigint                                 DEFAULT NULL COMMENT \'告警id\',\n    `subscribe_id` bigint                                 DEFAULT NULL COMMENT \'订阅id\',\n    `start_time`   timestamp(3) NULL                      DEFAULT NULL COMMENT \'开始时间\',\n    `action_id`    bigint                                 DEFAULT NULL COMMENT \'动作id\',\n    `status`       varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'状态\',\n    `end_time`     timestamp(3) NULL                      DEFAULT NULL COMMENT \'结束时间\',\n    `error`        text COLLATE utf8mb4_general_ci COMMENT \'异常\',\n    PRIMARY KEY (`id`),\n    KEY `idx_alert_id` (`alert_id`) USING BTREE,\n    KEY `idx_subscribe_id` (`subscribe_id`) USING BTREE,\n    KEY `idx_starttime` (`start_time`) USING BTREE,\n    KEY `idx_action_id` (`action_id`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('aff5143220be9b97954e868ef7c33b7c','CALL handleProcessTaskFormAttributeData();'),('b05aca4ebf76300752575635113eb33d','\nALTER TABLE `dr_scene`    ADD INDEX `idx_scene_id` (autoexec_scene_id ASC) USING BTREE;'),('b0d2708735f28c4016f6142057dd4533','\nCREATE TABLE `dr_preparation_job_phase_task`\n(\n    `id`              bigint    NOT NULL,\n    `uuid`            char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                                DEFAULT NULL,\n    `color`           varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                             DEFAULT NULL COMMENT \'颜色\',\n    `type`            enum (\'at\',\'mt\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                        DEFAULT NULL COMMENT \'类型\',\n    `name`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                            DEFAULT NULL COMMENT \'名称\',\n    `phase_id`        bigint                                                                                                   DEFAULT NULL COMMENT \'阶段id\',\n    `service_id`      bigint                                                                                                   DEFAULT NULL COMMENT \'服务id\',\n    `scene_id`        bigint                                                                                                   DEFAULT NULL COMMENT \'场景id\',\n    `autoexec_job_id` bigint                                                                                                   DEFAULT NULL COMMENT \'作业id\',\n    `description`     varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci                                            DEFAULT NULL COMMENT \'描述\',\n    `status`          enum (\'pending\',\'running\',\'succeed\',\'failed\',\'ignored\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'状态\',\n    `start_time`      timestamp NULL                                                                                           DEFAULT NULL COMMENT \'开始时间\',\n    `end_time`        timestamp NULL                                                                                           DEFAULT NULL COMMENT \'结束时间\',\n    `error`           text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,\n    `sort`            int                                                                                                      DEFAULT NULL COMMENT \'排序\',\n    `plan_time_cost`  int                                                                                                      DEFAULT NULL COMMENT \'计划耗时分钟\',\n    `plan_start_time` datetime                                                                                                 DEFAULT NULL COMMENT \'计划开始时间\',\n    `plan_end_time`   datetime                                                                                                 DEFAULT NULL COMMENT \'计划结束时间\',\n    PRIMARY KEY (`id`),\n    KEY `idx_phase_id` (`phase_id`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('b1162806b026140f6710e87840d1bb18','DROP TABLE IF EXISTS `processtask_form_extend_attribute`;'),('b1a98b4252e50b4c8c2c5308a9e2ef78','\nALTER TABLE `diagram_template_edge`\n    MODIFY COLUMN `id` bigint NOT NULL COMMENT \'id\' FIRST,\n    MODIFY COLUMN `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT \'名称\' AFTER `id`,\n    MODIFY COLUMN `rel_id` bigint NULL DEFAULT NULL COMMENT \'关系id\' AFTER `name`,\n    MODIFY COLUMN `ci_id` bigint NULL DEFAULT NULL COMMENT \'模型id\' AFTER `rel_id`,\n    MODIFY COLUMN `from_rel_id` bigint NULL DEFAULT NULL COMMENT \'上游关系id\' AFTER `ci_id`,\n    MODIFY COLUMN `to_rel_id` bigint NULL DEFAULT NULL COMMENT \'下游关系id\' AFTER `from_rel_id`,\n    MODIFY COLUMN `type` enum (\'ci\',\'rel\') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT \'类型\' AFTER `to_rel_id`,\n    MODIFY COLUMN `template_id` bigint NULL DEFAULT NULL COMMENT \'模板id\' AFTER `type`,    ADD COLUMN `config` text NULL COMMENT \'配置\' AFTER `template_id`;'),('b2258c7c0f264b32cf7c3636de5a17b3','\nALTER TABLE `eoa_step_user_content`\nDROP COLUMN `file_id_list_hash`,\n  CHANGE `id` `id` BIGINT NOT NULL   COMMENT \'id\',\n  CHANGE `eoa_id` `eoa_id` BIGINT NOT NULL   COMMENT \'eoa的id\',\n  CHANGE `eoa_step_id` `eoa_step_id` BIGINT NOT NULL   COMMENT \'eoa步骤的id\',\n  CHANGE `type` `type` VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL   COMMENT \'类型\',\n  CHANGE `content_hash` `content_hash` CHAR(32) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL   COMMENT \'内容的hash值\',\n  CHANGE `fcu` `fcu` CHAR(32) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL   COMMENT \'创建人\',\n  CHANGE `fcd` `fcd` TIMESTAMP(3) NOT NULL   COMMENT \'创建时间\',COMMENT=\'eoa步骤处理信息表\';'),('b275ee419ab2664594c19ec6788f9ae7','\nALTER TABLE `alert_attrtype`\n    ADD COLUMN `sort`   int     NULL COMMENT \'排序\' AFTER `is_normal`,    ADD COLUMN `is_top` tinyint NULL COMMENT \'是否置顶\' AFTER `sort`;'),('b2c2ba49d5f17e9b845ceba38a218429','\nALTER TABLE `form_attribute_data`    ADD COLUMN `attribute_key` VARCHAR(100) NULL   COMMENT \'属性英文名\' AFTER `attribute_label`;'),('b2c484a65e521f7b18657a016468bf78','ALTER TABLE `diagram_catalog`    ADD COLUMN `user_id`    char(32) NULL COMMENT \'用户id\' AFTER `config`,    ADD COLUMN `is_private` tinyint  NULL COMMENT \'是否私有属性\' AFTER `user_id`;'),('b2f3ad75ccab9fe85621eed90ff9f2a4','\nALTER TABLE `alert_subscribe_audit`    ADD COLUMN `result` text NULL COMMENT \'结果\' AFTER `error`;'),('b41ee79f97d9014c4b3b540c990bbef5','\nCREATE PROCEDURE handleProcessTaskFormAttributeData()\nBEGIN\n    DECLARE rowNum BIGINT DEFAULT 0;\n    DECLARE currentPage INT DEFAULT 1;\n    DECLARE pageSize INT DEFAULT 100;\n    DECLARE pageCount INT DEFAULT 0;\n    SELECT COUNT(1) INTO rowNum FROM `processtask_formattribute_data`;\n    IF rowNum > 0 THEN\n        SET @lastStamp = -1;\n        SET @sequence = 0;\n        SET pageCount = CEIL(rowNum / pageSize);\n        WHILE currentPage <= pageCount DO\n            BEGIN\n                DECLARE done INT DEFAULT FALSE;\n                DECLARE v_id BIGINT;\n                DECLARE v_processTaskId BIGINT;\n                DECLARE v_type VARCHAR(50);\n                DECLARE v_attributeLabel VARCHAR(50);\n                DECLARE v_attributeUuid CHAR(32);\n                DECLARE v_formUuid CHAR(32);\n                DECLARE v_data MEDIUMTEXT;\n                DECLARE startNum INT DEFAULT (currentPage - 1) * pageSize;\n                DECLARE cur CURSOR FOR SELECT a.`processtask_id`, a.`type`, a.`attribute_label`, a.`attribute_uuid`, a.`data`, b.`form_uuid`\n                                       FROM `processtask_formattribute_data` a\n                                       JOIN `processtask_form` b ON b.`processtask_id` = a.`processtask_id`\n                                       ORDER BY a.`processtask_id`, a.`sort`\n                                       LIMIT startNum, pageSize;\n                DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n                SET @batchInsertSql_form_attribute_data = NULL;\n                SET @batchInsertSql_processtask_formattribute = NULL;\n                OPEN cur;\n                read_loop: LOOP\n                    FETCH cur INTO v_processTaskId, v_type, v_attributeLabel, v_attributeUuid, v_data, v_formUuid;\n                    IF done THEN\n                        LEAVE read_loop;\n                    END IF;\n                    IF v_type IS NULL THEN\n			            SET v_type = \'\';\n                    END IF;\n                    IF v_attributeLabel IS NULL THEN\n                        SET v_attributeLabel = \'\';\n                    END IF;\n                    IF v_data IS NULL THEN\n                        SET v_data = \'\';\n                    END IF;\n                    SET v_id = generateSnowflakeId();\n                    IF @batchInsertSql_form_attribute_data IS NULL THEN\n                        SET @batchInsertSql_form_attribute_data = CONCAT(\'INSERT INTO `form_attribute_data` (`id`, `form_uuid`, `handler`, `attribute_label`, `attribute_uuid`, `data`) VALUES\', \' (\', v_id, \', \\\'\', v_formUuid, \'\\\', \\\'\', v_type, \'\\\', \\\'\', v_attributeLabel, \'\\\', \\\'\', v_attributeUuid, \'\\\', \\\'\', v_data, \'\\\')\');\n                    ELSE\n                        SET @batchInsertSql_form_attribute_data = CONCAT(@batchInsertSql_form_attribute_data, \', (\', v_id, \', \\\'\', v_formUuid, \'\\\', \\\'\', v_type, \'\\\', \\\'\', v_attributeLabel, \'\\\', \\\'\', v_attributeUuid, \'\\\', \\\'\', v_data, \'\\\')\');\n                    END IF;\n                    IF @batchInsertSql_processtask_formattribute IS NULL THEN\n                        SET @batchInsertSql_processtask_formattribute = CONCAT(\'INSERT INTO `processtask_formattribute` (`processtask_id`, `form_attribute_data_id`) VALUES\', \' (\', v_processTaskId, \',\', v_id, \')\');\n                    ELSE\n                        SET @batchInsertSql_processtask_formattribute = CONCAT(@batchInsertSql_processtask_formattribute, \', (\', v_processTaskId, \',\', v_id, \')\');\n                    END IF;\n                END LOOP;\n                CLOSE cur;\n                PREPARE stmt_1 FROM @batchInsertSql_form_attribute_data;\n                EXECUTE stmt_1;\n                DEALLOCATE PREPARE stmt_1;\n                PREPARE stmt_2 FROM @batchInsertSql_processtask_formattribute;\n                EXECUTE stmt_2;\n                DEALLOCATE PREPARE stmt_2;\n                SET @batchInsertSql_form_attribute_data = NULL;\n                SET @batchInsertSql_processtask_formattribute = NULL;\n            END;\n            SET currentPage = currentPage + 1;\n        END WHILE;\n    END IF;END $$'),('b62568ee83108b9370784cd486ba8748','\nALTER TABLE `cmdb_resourcecenter_account`    CHANGE `account` `account` VARCHAR (100) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT \'账号\';'),('b701860fb22b455741834c65cc8a5e0e','ALTER TABLE `autoexec_job_phase_node` DROP INDEX `uni_id`;'),('b93251dabeca1d2e016de94200536eb6','ALTER TABLE `datasource` DROP PRIMARY KEY;'),('b96bf948e4a4bccb1aa348fc4e5cd030','\nCREATE TABLE `alert_adaptor`\n(\n    `id`           bigint NOT NULL COMMENT \'id\',\n    `alerttype_id` bigint                                  DEFAULT NULL COMMENT \'告警类型id\',\n    `name`         varchar(50) COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT \'唯一标识\',\n    `label`        varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'名称\',\n    `file_id`      bigint                                  DEFAULT NULL COMMENT \'附件id\',\n    PRIMARY KEY (`id`)\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('b97b06b3dbe2d6c2b3d4c1349054104d','\nALTER TABLE `processtask_collection_definition`\n    DROP COLUMN `system`,\n    DROP COLUMN `request`,    DROP COLUMN `env`;'),('bac7f8b019340912b82ca6e0a9e45cfc','\nALTER TABLE `server_status`    ADD COLUMN `ip` VARCHAR (50) NULL COMMENT \'应用服务器IP\' AFTER `heartbeat_time`;'),('bb9b17f140fa7ceb6839919434ca2514','\nALTER TABLE `deploy_app_env_auto_config`    ADD COLUMN `is_empty` TINYINT (1) DEFAULT 0 NOT NULL COMMENT \'是否设为空\' AFTER `value`;'),('bc60809ab8896f033d6b5db516940642','\nALTER TABLE `deploy_app_config_env_attr`MODIFY COLUMN `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT \'text\' COMMENT \'变量类型\' AFTER `key`;'),('bd0aebcad53c0d9ff4eea9efa4187717','\nALTER TABLE `mq_subscribe`    ADD COLUMN `handler` varchar(50) NOT NULL DEFAULT \'artemis\' COMMENT \'消息队列类型\' AFTER `server_id`;'),('bd2485ceb20761cc223bf066f9843fb9','\nALTER TABLE `form_attribute`    ADD COLUMN `key` VARCHAR(100) NULL   COMMENT \'属性英文名\' AFTER `uuid`;'),('bd570115ad1c2ac8b4dc177107e68124','\nCREATE TABLE `processtask_step_cost` (\n    `id` bigint NOT NULL COMMENT \'ID\',\n    `processtask_id` bigint NOT NULL COMMENT \'工单id\',\n    `pr