70025','\nCREATE FUNCTION `generateSnowflakeId`() RETURNS BIGINT DETERMINISTIC\nBEGIN\n    DECLARE SCHEDULE_SERVER_ID BIGINT DEFAULT 1;\n    DECLARE START_TIMESTAMP BIGINT DEFAULT 1577808000;\n    DECLARE SEQUENCE_BIT BIGINT DEFAULT 13;\n    DECLARE MACHINE_BIT BIGINT DEFAULT 10;\n    DECLARE TIMESTAMP_LEFT BIGINT DEFAULT SEQUENCE_BIT + MACHINE_BIT;\n    DECLARE MAX_SEQUENCE BIGINT DEFAULT ~(-1 << SEQUENCE_BIT);\n    DECLARE MAX_MACHINE_ID BIGINT DEFAULT ~(-1 << MACHINE_BIT);\n    DECLARE machineIdPart BIGINT DEFAULT (SCHEDULE_SERVER_ID & MAX_MACHINE_ID) << SEQUENCE_BIT;\n    DECLARE currentStamp BIGINT;\n    SET currentStamp = UNIX_TIMESTAMP(NOW());\n    IF currentStamp < @lastStamp THEN\n        WHILE currentStamp < @lastStamp DO\n		    SET currentStamp = UNIX_TIMESTAMP(NOW());\n        END WHILE;\n    END IF;\n    IF currentStamp = @lastStamp THEN\n        SET @sequence = (@sequence + 1) & MAX_SEQUENCE;\n        IF @sequence = 0 THEN\n            WHILE currentStamp < @lastStamp DO\n		        SET currentStamp = UNIX_TIMESTAMP(NOW());\n            END WHILE;\n        END IF;\n    ELSE\n        SET @sequence = 0;\n    END IF;\n    SET @lastStamp = currentStamp;\n    RETURN ((currentStamp - START_TIMESTAMP) << TIMESTAMP_LEFT) | machineIdPart | @sequence;END $$'),('eef525a1fd04eb5fce539c78b3fdbcd1','\nCREATE TABLE IF NOT EXISTS `processtask_collection_integration_audit`\n(\n    `collection_id` bigint NOT NULL COMMENT \'集合id\',\n    `audit_id`      bigint NOT NULL COMMENT \'审计id\',\n    `action_uuid`   char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT \'动作的uuid\',\n    PRIMARY KEY (`collection_id`, `audit_id`) USING BTREE,\n    KEY `idx_audit_id` (`audit_id`) USING BTREE,\n    KEY `idx_integration_uuid` (`action_uuid`) USING BTREE\n) ENGINE = InnoDB\n  DEFAULT CHARSET = utf8mb4  COLLATE = utf8mb4_general_ci;'),('ef1c373e960be5168184213a6f73afd2','\nALTER TABLE `deploy_app_env_auto_config`    CHANGE `value` `value` TEXT CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT \'变量值\';'),('ef93520a3aa9de685f117a71d29079c5','\nALTER TABLE `alert_event_handler_audit`    ADD COLUMN `config` text NULL COMMENT \'事件配置\' AFTER `error`;'),('f0861a97b569ab574bc1d17977f06971','TRUNCATE `process_workcenter_thead` ;'),('f1d808a6147f01cb3c56251d02e899a2','\nCREATE TABLE  IF NOT EXISTS `form_attribute_data` (\n  `id` bigint NOT NULL COMMENT \'id\',\n  `form_uuid` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT \'表单uuid\',\n  `handler` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT \'类型\',\n  `attribute_label` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT \'属性名\',\n  `attribute_uuid` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT \'属性uuid\',\n  `data` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT \'属性值,json格式\',\n  PRIMARY KEY (`id`) USING BTREE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'表单实例属性当前值\';'),('f3388ac7a874a7957508e3c9c175595c','ALTER TABLE `runner` ADD COLUMN `info` text NULL COMMENT \'额外信息\' AFTER `status`;'),('f44b9a3c931ff7b174aab13bf28487dd','\nALTER TABLE `form_extend_attribute`    CHANGE `parent_uuid` `parent_uuid` CHAR(32) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL   COMMENT \'属性父级uuid\';'),('f46c75b012ce1bb00814bc103717535c','\nALTER TABLE `deploy_job`MODIFY COLUMN `app_module_id` bigint NULL COMMENT \'系统模块id\' AFTER `app_system_id`;'),('f4b21f00428492ff0af3ced25cf992aa','\nALTER TABLE `inspect_alert_everyday`    CHANGE `alert_tips` `alert_tips` VARCHAR (255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT \'告警提示\';'),('f52c210b70475db38e0d333c1e2260a4','\nreplace into cmdb_viewconst (id, name, label, sort, show_type)values (2, \'_ciLabel\', \'模型\', 3, \'all\');'),('f6418fa35b19ff470de2c1f7acccf843','ALTER TABLE `inspect_alert_everyday` ADD PRIMARY KEY (`resource_id`, `report_time`, `alert_object` (500));'),('f642c33